import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.1lnE8eph.js";const p=JSON.parse('{"title":"Table Virtualization and Expanded Bus Demo","description":"","frontmatter":{},"headers":[],"relativePath":"specs/003-table-virtualization.md","filePath":"specs/003-table-virtualization.md"}'),r={name:"specs/003-table-virtualization.md"};function l(o,e,s,d,c,u){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="table-virtualization-and-expanded-bus-demo" tabindex="-1">Table Virtualization and Expanded Bus Demo <a class="header-anchor" href="#table-virtualization-and-expanded-bus-demo" aria-label="Permalink to &quot;Table Virtualization and Expanded Bus Demo&quot;">​</a></h1><h2 id="_1-scope" tabindex="-1">1. Scope <a class="header-anchor" href="#_1-scope" aria-label="Permalink to &quot;1. Scope&quot;">​</a></h2><p>Implement TanStack virtualization in the shared table and demonstrate it with more bus lines.</p><p>Delivered in <a href="https://github.com/airafa/bus-map/pull/3" target="_blank" rel="noreferrer">PR #3</a>. This specification supersedes the initial five-route demo size in <a href="./001-init">001-init.md</a>.</p><h2 id="_2-shared-table-virtualization" tabindex="-1">2. Shared table virtualization <a class="header-anchor" href="#_2-shared-table-virtualization" aria-label="Permalink to &quot;2. Shared table virtualization&quot;">​</a></h2><ul><li>Use <code>@tanstack/react-virtual</code> with the existing shared TanStack Table renderer.</li><li>Make virtualization opt-in and enable it for the main bus schedule.</li><li>Keep short stops-dialog and design-system reference tables fully rendered.</li><li>Render viewport rows with two overscan rows on each side instead of mounting the entire dataset.</li><li>Measure row heights and the sticky-header offset.</li><li>Use stable table row IDs when scrolling, sorting and selecting.</li><li>Keep focused rows mounted so scrolling does not discard keyboard focus.</li><li>Expose the complete accessible row count, including headers, and logical <code>aria-rowindex</code> values on mounted rows.</li><li>Allow scrolling to the final row without clipping it.</li></ul><h2 id="_3-gantt-lifecycle-and-preserved-behavior" tabindex="-1">3. Gantt lifecycle and preserved behavior <a class="header-anchor" href="#_3-gantt-lifecycle-and-preserved-behavior" aria-label="Permalink to &quot;3. Gantt lifecycle and preserved behavior&quot;">​</a></h2><ul><li>Mount Gantt components only for rendered rows.</li><li>Unmount offscreen Gantts and stop their live clock updates.</li><li>Continue live updates for mounted Gantts.</li><li>Preserve sorting, reset to input order, row selection and adjacent-column resizing.</li><li>Keep all geographic routes on the map regardless of which schedule rows are mounted.</li></ul><h2 id="_4-demo-data" tabindex="-1">4. Demo data <a class="header-anchor" href="#_4-demo-data" aria-label="Permalink to &quot;4. Demo data&quot;">​</a></h2><ul><li>Expand the dataset to 30 distinct bus lines and 150 stops.</li><li>Keep route identifiers and row identities distinct.</li><li>Retain representative routes and schedules that demonstrate scrolling, sorting and selection.</li></ul><h2 id="_5-validation-and-delivery" tabindex="-1">5. Validation and delivery <a class="header-anchor" href="#_5-validation-and-delivery" aria-label="Permalink to &quot;5. Validation and delivery&quot;">​</a></h2><ul><li>Leave a runnable browser regression using the existing browser-check approach.</li><li>At a 1200x700 viewport, verify fewer mounted schedule/Gantt rows than the 30-row dataset.</li><li>Verify offscreen unmounting and stopped clock updates, continued visible-row updates, final-row reachability, sorting/reset, selection, resizing and keyboard-focus retention.</li><li>Verify that the map still contains all 30 routes.</li><li>Run existing design-system and transit tests, strict TypeScript checking and the production Pages-mode build.</li><li>Deliver on a feature branch through a pull request against <code>main</code>.</li><li>Publish to the GitHub Pages repository when requested; publication is separate from merging the application PR.</li></ul>',12)])])}const b=a(r,[["render",l]]);export{p as __pageData,b as default};
